// ========================================
// MOTOR DE INFERÊNCIA - PESQUISA OPERACIONAL
// Análise de VPL, Sensibilidade, Monte Carlo, LTV e Consórcio
// ========================================

const form = $("Simulador de Amortização Inteligente").first().json;
const api = $("Buscar Taxa Selic").first().json;

// --- INPUTS ---
const modalidade = form["modalidade"];
const valorBem = parseFloat(form["valor_bem"]) || 0;
const valorEntrada = parseFloat(form["valor_entrada"]) || 0;
const dividaTotal = parseFloat(form["valor_divida"]);
const jurosAnualBanco = parseFloat(form["taxa_juros"]) / 100;
const aporteExtra = parseFloat(form["valor_aporte"]) || 0;
const prazoMeses = parseInt(form["prazo_meses"]) || 12;
const tipoDivida = form["tipo_divida"];
const taxaAdminConsorcio = parseFloat(form["taxa_admin_consorcio"]) || 0;
const prazoConsorcio = parseInt(form["prazo_consorcio"]) || 0;
const tempoContemplacao = parseInt(form["tempo_contemplacao"]) || 0;
const valorAluguel = parseFloat(form["valor_aluguel"]) || 0;
const valorLance = parseFloat(form["valor_lance"]) || 0;

// --- DADOS DE MERCADO ---
const selicDiaria = parseFloat(api.valor);
const selicAnualBruta = (Math.pow((1 + selicDiaria/100), 252) - 1);

// IR Regressivo
let aliquotaIR = 0.225;
if (prazoMeses >= 24) aliquotaIR = 0.15;
else if (prazoMeses >= 12) aliquotaIR = 0.175;
else if (prazoMeses >= 6) aliquotaIR = 0.20;

const multiplicadorIR = 1 - aliquotaIR;
const selicAnualLiquida = selicAnualBruta * multiplicadorIR;

// IPCA (se pós-fixada)
const dadosIPCA = $("Buscar IPCA").all();
const ipcaAcumulado = dadosIPCA.reduce((acc, item) => {
  return acc * (1 + parseFloat(item.json.valor) / 100);
}, 1);
const ipcaAnual = ((ipcaAcumulado - 1) * 100);

let custoRealDivida = jurosAnualBanco * 100;
if (tipoDivida === "Pós-fixada (IPCA+)") {
  custoRealDivida = (jurosAnualBanco * 100) + ipcaAnual;
}

// ========================================
// MÓDULO 1: ANÁLISE DE LTV (LOAN-TO-VALUE)
// ========================================
let ltvAtual = 0;
let valorFinanciado = 0;
let decisaoEntrada = "";
let analiseEntrada = "";
let entradaOtima = 0;
let entradaMinima = 0;
let entradaMaxima = 0;

if (modalidade === "Análise de Entrada (LTV)" && valorBem > 0) {
  valorFinanciado = valorBem - valorEntrada;
  ltvAtual = (valorFinanciado / valorBem) * 100;

  // Regra de Ouro: Se Selic Líquida > Juros, entrada mínima. Se Juros > Selic, entrada máxima.
  const selicLiquidaPercent = selicAnualLiquida * 100;

  if (selicLiquidaPercent > custoRealDivida) {
    decisaoEntrada = "ENTRADA MÍNIMA";
    entradaOtima = valorBem * 0.20; // 20% mínimo típico
    analiseEntrada = `Como a Selic Líquida (${selicLiquidaPercent.toFixed(2)}%) supera o custo da dívida (${custoRealDivida.toFixed(2)}%), a estratégia ótima é dar a ENTRADA MÍNIMA e manter o capital investido.`;
  } else {
    decisaoEntrada = "ENTRADA MÁXIMA";
    entradaOtima = valorBem * 0.50; // 50% para melhor faixa de juros
    analiseEntrada = `Como o custo da dívida (${custoRealDivida.toFixed(2)}%) supera a Selic Líquida (${selicLiquidaPercent.toFixed(2)}%), a estratégia ótima é dar a ENTRADA MÁXIMA possível sem comprometer sua reserva de emergência.`;
  }

  entradaMinima = valorBem * 0.20;
  entradaMaxima = valorBem * 0.50;
}

// ========================================
// MÓDULO 2: FINANCIAMENTO VS CONSÓRCIO
// ========================================
let custoTotalFinanciamento = 0;
let custoTotalConsorcio = 0;
let custoOportunidadeEspera = 0;
let decisaoModalidade = "";
let analiseModalidade = "";
let taxaEquivalenteConsorcio = 0;

if (modalidade === "Financiamento vs Consórcio" && prazoConsorcio > 0) {
  // Custo Total do Financiamento (Sistema SAC simplificado)
  const taxaMensalFinanc = Math.pow(1 + (custoRealDivida/100), 1/12) - 1;
  const parcelaFinanc = dividaTotal * (taxaMensalFinanc * Math.pow(1 + taxaMensalFinanc, prazoMeses)) / (Math.pow(1 + taxaMensalFinanc, prazoMeses) - 1);
  custoTotalFinanciamento = (parcelaFinanc * prazoMeses) - dividaTotal;

  // Custo Total do Consórcio
  const custoAdministracao = dividaTotal * (taxaAdminConsorcio / 100);
  const fundoReserva = dividaTotal * 0.02; // Estimativa 2%
  const seguroConsorcio = dividaTotal * 0.01; // Estimativa 1%
  custoTotalConsorcio = custoAdministracao + fundoReserva + seguroConsorcio;

  // Taxa Equivalente Mensal do Consórcio
  taxaEquivalenteConsorcio = (Math.pow(1 + (custoTotalConsorcio / dividaTotal), 1/prazoConsorcio) - 1) * 100;

  // Custo de Oportunidade da Espera (Aluguel durante contemplação)
  custoOportunidadeEspera = valorAluguel * tempoContemplacao;

  // Ajuste do Lance (se houver)
  let custoLance = 0;
  if (valorLance > 0) {
    // O lance antecipa a entrada, perdendo rendimento
    custoLance = valorLance * (selicAnualLiquida * (tempoContemplacao/12));
  }

  const custoRealConsorcio = custoTotalConsorcio + custoOportunidadeEspera + custoLance;

  if (custoTotalFinanciamento < custoRealConsorcio) {
    decisaoModalidade = "FINANCIAMENTO";
    analiseModalidade = `O financiamento é a solução ótima. Custo Total: R$ ${custoTotalFinanciamento.toFixed(2)} vs Consórcio: R$ ${custoRealConsorcio.toFixed(2)} (incluindo R$ ${custoOportunidadeEspera.toFixed(2)} de aluguel durante ${tempoContemplacao} meses de espera).`;
  } else {
    decisaoModalidade = "CONSÓRCIO";
    analiseModalidade = `O consórcio é a solução ótima. Custo Total: R$ ${custoRealConsorcio.toFixed(2)} vs Financiamento: R$ ${custoTotalFinanciamento.toFixed(2)}. Requer disciplina e ${tempoContemplacao} meses de espera estimados.`;
  }
}

// ========================================
// MÓDULO 3: AMORTIZAÇÃO VS INVESTIMENTO (ORIGINAL)
// ========================================
const custoMensalBanco = Math.pow(1 + (custoRealDivida/100), 1/12) - 1;
const rendimentoMensalSelic = Math.pow(1 + selicAnualLiquida, 1/12) - 1;

let vplAmortizar = 0;
let vplInvestir = 0;

if (aporteExtra > 0) {
  for (let t = 1; t <= prazoMeses; t++) {
      vplAmortizar += (aporteExtra * custoMensalBanco) / Math.pow(1 + rendimentoMensalSelic, t);
  }

  for (let t = 1; t <= prazoMeses; t++) {
      vplInvestir += (aporteExtra * rendimentoMensalSelic) / Math.pow(1 + rendimentoMensalSelic, t);
  }
}

// --- ANÁLISE DE SENSIBILIDADE (Break-even) ---
const selicEquilibrio = (custoRealDivida / multiplicadorIR);
const margemSeguranca = ((selicAnualBruta * 100) - selicEquilibrio);
const margemSegurancaIPCA = 7.20 - ipcaAnual;

// --- SIMULAÇÃO DE MONTE CARLO (1000 cenários com Box-Muller) ---
const numSimulacoes = 1000;
const volSelic = 0.015;
const volIPCA = 0.01;

function normalRandom(mean, std) {
    let u = 0, v = 0;
    while(u === 0) u = Math.random();
    while(v === 0) v = Math.random();
    let num = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
    return num * std + mean;
}

let cenariosFavoraveis = 0;
let ganhosAcumulados = 0;
let vplMedioInvestir = 0;
let vplMedioAmortizar = 0;

if (aporteExtra > 0) {
  for (let i = 0; i < numSimulacoes; i++) {
    const selicSimuladaAnual = normalRandom(selicAnualBruta, volSelic);
    const rendimentoLiqSimulado = selicSimuladaAnual * multiplicadorIR;

    const ipcaSimuladoAnual = normalRandom(ipcaAnual / 100, volIPCA);

    let custoSimulado = jurosAnualBanco;
    if (tipoDivida === "Pós-fixada (IPCA+)") {
      custoSimulado = jurosAnualBanco + ipcaSimuladoAnual;
    }

    const rendMensal = Math.pow(1 + rendimentoLiqSimulado, 1/12) - 1;
    const custoMensal = Math.pow(1 + custoSimulado, 1/12) - 1;

    let vplInvestirSim = 0;
    let vplAmortizarSim = 0;

    for (let t = 1; t <= prazoMeses; t++) {
      vplInvestirSim += (aporteExtra * rendMensal) / Math.pow(1 + rendMensal, t);
      vplAmortizarSim += (aporteExtra * custoMensal) / Math.pow(1 + rendMensal, t);
    }

    vplMedioInvestir += vplInvestirSim;
    vplMedioAmortizar += vplAmortizarSim;

    if (vplInvestirSim > vplAmortizarSim) {
      cenariosFavoraveis++;
    }

    ganhosAcumulados += (vplInvestirSim - vplAmortizarSim);
  }
}

const confiancaMonteCarlo = (cenariosFavoraveis / numSimulacoes) * 100;
vplMedioInvestir = vplMedioInvestir / numSimulacoes;
vplMedioAmortizar = vplMedioAmortizar / numSimulacoes;
const expectativaGanhoMedio = ganhosAcumulados / numSimulacoes;

// --- PROJEÇÃO DE RIQUEZA LÍQUIDA ---
const ganhoInvestimento = aporteExtra * Math.pow((1 + selicAnualLiquida), prazoMeses/12);
const economiaAmortizacao = aporteExtra * (custoRealDivida/100) * (prazoMeses/12);

const patrimonioFinalInvestir = ganhoInvestimento;
const patrimonioFinalAmortizar = economiaAmortizacao;
const diferencaPatrimonial = patrimonioFinalInvestir - patrimonioFinalAmortizar;

// --- CÁLCULO DE PARCELAS ECONOMIZADAS ---
const taxaMensal = custoRealDivida / 100 / 12;
const parcelasEconomizadas = aporteExtra > 0 ? Math.log(1 + (aporteExtra * taxaMensal) / (dividaTotal * taxaMensal)) / Math.log(1 + taxaMensal) : 0;

// --- VEREDITO ---
const decisao = vplInvestir > vplAmortizar ? "INVESTIR" : "AMORTIZAR";
const ganhoReal = Math.abs(vplInvestir - vplAmortizar);
const deltaVPL = vplInvestir - vplAmortizar;
const spreadReal = (selicAnualLiquida * 100) - custoRealDivida;

let analise = "";
let insightPO = "";

if (decisao === "AMORTIZAR") {
  analise = "No cenário atual, reduzir o passivo gera mais valor presente do que aplicar no mercado.";
  insightPO = `A decisão de amortizar é a solução ótima atual. O VPL da economia de juros (R$ ${vplAmortizar.toFixed(2)}) supera o VPL do rendimento líquido disponível no mercado (R$ ${vplInvestir.toFixed(2)}).`;
} else {
  analise = "No cenário atual, seu capital trabalha com mais eficiência no mercado do que amortizando o passivo.";
  insightPO = `A decisão de investir é a solução ótima atual. O VPL do rendimento (R$ ${vplInvestir.toFixed(2)}) supera o VPL da economia de juros (R$ ${vplAmortizar.toFixed(2)}). Mesmo que a Selic caia até ${selicEquilibrio.toFixed(2)}% (margem de ${margemSeguranca.toFixed(2)}%), a decisão permanece válida.`;
}

const dataHora = new Date().toLocaleString("pt-BR", {timeZone: "America/Sao_Paulo"});

return {
  modalidade,
  decisao,
  analise,
  insight_po: insightPO,
  grau_confianca: `${confiancaMonteCarlo.toFixed(0)}% (Baseado em Simulação de Monte Carlo com Box-Muller)`,
  confianca_percentual: confiancaMonteCarlo.toFixed(0),

  // LTV
  ltv_atual: ltvAtual.toFixed(2),
  valor_bem: valorBem.toFixed(2),
  valor_entrada: valorEntrada.toFixed(2),
  valor_financiado: valorFinanciado.toFixed(2),
  decisao_entrada: decisaoEntrada,
  analise_entrada: analiseEntrada,
  entrada_otima: entradaOtima.toFixed(2),
  entrada_minima: entradaMinima.toFixed(2),
  entrada_maxima: entradaMaxima.toFixed(2),

  // Consórcio
  decisao_modalidade: decisaoModalidade,
  analise_modalidade: analiseModalidade,
  custo_total_financiamento: custoTotalFinanciamento.toFixed(2),
  custo_total_consorcio: custoTotalConsorcio.toFixed(2),
  custo_oportunidade_espera: custoOportunidadeEspera.toFixed(2),
  taxa_equivalente_consorcio: taxaEquivalenteConsorcio.toFixed(4),
  tempo_contemplacao: tempoContemplacao,

  selic_anual_bruta: (selicAnualBruta * 100).toFixed(2),
  selic_anual_liquida: (selicAnualLiquida * 100).toFixed(2),
  selic_equilibrio: selicEquilibrio.toFixed(2),
  margem_seguranca_selic: margemSeguranca.toFixed(2),
  margem_seguranca_ipca: margemSegurancaIPCA.toFixed(2),
  limite_ipca: "7.20",
  custo_divida_nominal: (jurosAnualBanco * 100).toFixed(2),
  custo_divida_real: custoRealDivida.toFixed(2),
  ipca_acumulado: ipcaAnual.toFixed(2),
  spread_real: spreadReal.toFixed(2),

  vpl_investir: vplInvestir.toFixed(2),
  vpl_amortizar: vplAmortizar.toFixed(2),
  delta_vpl: deltaVPL.toFixed(2),
  ganho_vpl: ganhoReal.toFixed(2),
  ganho_investimento: ganhoInvestimento.toFixed(2),
  economia_amortizacao: economiaAmortizacao.toFixed(2),
  diferenca_patrimonial: diferencaPatrimonial.toFixed(2),
  patrimonio_final_investir: patrimonioFinalInvestir.toFixed(2),
  patrimonio_final_amortizar: patrimonioFinalAmortizar.toFixed(2),

  parcelas_economizadas: Math.floor(parcelasEconomizadas),

  aliquota_ir: (aliquotaIR * 100).toFixed(1),
  prazo_meses: prazoMeses,
  valor_aporte: aporteExtra.toFixed(2),
  valor_divida: dividaTotal.toFixed(2),
  tipo_divida: tipoDivida,

  simulacoes_total: numSimulacoes,
  cenarios_favoraveis: cenariosFavoraveis,
  vpl_medio_investir: vplMedioInvestir.toFixed(2),
  vpl_medio_amortizar: vplMedioAmortizar.toFixed(2),
  expectativa_ganho_medio: expectativaGanhoMedio.toFixed(2),
  volatilidade_selic: (volSelic * 100).toFixed(2),
  volatilidade_ipca: (volIPCA * 100).toFixed(2),

  status_robustez: parseFloat(margemSeguranca) > 2 ? "✅ Decisão Robusta" : "⚠️ Decisão Sensível",

  data_hora: dataHora,
  selic_diaria_bcb: selicDiaria.toFixed(5)
};
